// 该脚本内容来自 autohue.js | https://unpkg.com/autohue.js@1.0.3/dist/autohue.cjs.js | https://github.com/Auto-Plugin/autohue.js
/**
 * @name: autohue.js
 * @author: Larry Zhu
 * @version: 1.0.3
 * @description: 一个自动提取图片主题色让图片和背景融为一体的工具
 * @license: MIT
 */"use strict";
 function rgbToLabamtu(r, g, b) {
    let R = r / 255, G = g / 255, B = b / 255;
    R = R > .04045 ? Math.pow((R + .055) / 1.055, 2.4) : R / 12.92;
    G = G > .04045 ? Math.pow((G + .055) / 1.055, 2.4) : G / 12.92;
    B = B > .04045 ? Math.pow((B + .055) / 1.055, 2.4) : B / 12.92;
    let X = R * .4124 + G * .3576 + B * .1805;
    let Y = R * .2126 + G * .7152 + B * .0722;
    let Z = R * .0193 + G * .1192 + B * .9505;
    X = X / .95047;
    Y = Y / 1;
    Z = Z / 1.08883;
    const f = (t) => t > .008856 ? Math.pow(t, .3333333333333333) : 7.787 * t + .13793103448275862;
    const fx = f(X);
    const fy = f(Y);
    const fz = f(Z);
    const L = 116 * fy - 16;
    const a = 500 * (fx - fy);
    const bVal = 200 * (fy - fz);
    return [
        L,
        a,
        bVal
    ];
}
function labDistanceamtu(lab1, lab2) {
    const dL = lab1[0] - lab2[0];
    const da = lab1[1] - lab2[1];
    const db = lab1[2] - lab2[2];
    return Math.sqrt(dL * dL + da * da + db * db);
}
function rgbToHexamtu(rgb) {
    return "#" + rgb.map((v) => {
        const hex = Math.round(v).toString(16);
        return hex.length === 1 ? "0" + hex : hex;
    }).join("");
}
function loadImageamtu(imageSource) {
    return new Promise((resolve, reject) => {
        let img;
        if (typeof imageSource === "string") {
            img = new Image();
            img.crossOrigin = "Anonymous";
            img.src = imageSource;
        } else img = imageSource;
        if (img.complete) resolve(img);
else {
            img.onload = () => resolve(img);
            img.onerror = (err) => reject(err);
        }
    });
}
function getImageDataFromImageamtu(img, maxSize = 100) {
    const canvas = document.createElement("canvas");
    let width = img.naturalWidth;
    let height = img.naturalHeight;
    if (width > maxSize || height > maxSize) {
        const scale = Math.min(maxSize / width, maxSize / height);
        width = Math.floor(width * scale);
        height = Math.floor(height * scale);
    }
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("无法获取 Canvas 上下文");
    ctx.drawImage(img, 0, 0, width, height);
    return ctx.getImageData(0, 0, width, height);
}
function clusterPixelsByConditionamtu(imageData, condition, threshold = 10) {
    const MAX_CLUSTERS = 24;
    const clusters = [];
    const data = imageData.data;
    const width = imageData.width;
    const height = imageData.height;
    for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        if (!condition(x, y)) continue;
        const index = (y * width + x) * 4;
        if (data[index + 3] === 0) continue;
        const r = data[index];
        const g = data[index + 1];
        const b = data[index + 2];
        const lab = rgbToLabamtu(r, g, b);
        let added = false;
        for (const cluster of clusters) {
            const d = labDistanceamtu(lab, cluster.averageLab);
            if (d < threshold) {
                cluster.count++;
                cluster.sumRgb[0] += r;
                cluster.sumRgb[1] += g;
                cluster.sumRgb[2] += b;
                cluster.sumLab[0] += lab[0];
                cluster.sumLab[1] += lab[1];
                cluster.sumLab[2] += lab[2];
                cluster.averageRgb = [
                    cluster.sumRgb[0] / cluster.count,
                    cluster.sumRgb[1] / cluster.count,
                    cluster.sumRgb[2] / cluster.count
                ];
                cluster.averageLab = [
                    cluster.sumLab[0] / cluster.count,
                    cluster.sumLab[1] / cluster.count,
                    cluster.sumLab[2] / cluster.count
                ];
                added = true;
                break;
            }
        }
        if (!added && clusters.length < MAX_CLUSTERS) clusters.push({
            count: 1,
            sumRgb: [
                r,
                g,
                b
            ],
            sumLab: [
                lab[0],
                lab[1],
                lab[2]
            ],
            averageRgb: [
                r,
                g,
                b
            ],
            averageLab: [
                lab[0],
                lab[1],
                lab[2]
            ]
        });
    }
    return clusters;
}
function __handleAutoHueOptionsamtu(options) {
    if (!options) options = {};
    const { maxSize = 100 } = options;
    let threshold = options.threshold || 10;
    if (typeof threshold === "number") threshold = {
        primary: threshold,
        left: threshold,
        right: threshold,
        top: threshold,
        bottom: threshold
    };
else threshold = {
        primary: threshold.primary || 10,
        left: threshold.left || 10,
        right: threshold.right || 10,
        top: threshold.top || 10,
        bottom: threshold.bottom || 10
    };
    return {
        maxSize,
        threshold
    };
}
async function colorPickeramtu(imageSource, options) {
    const { maxSize, threshold } = __handleAutoHueOptionsamtu(options);
    const img = await loadImageamtu(imageSource);
    const imageData = getImageDataFromImageamtu(img, maxSize);
    let clusters = clusterPixelsByConditionamtu(imageData, () => true, threshold.primary);
    clusters.sort((a, b) => b.count - a.count);
    const primaryCluster = clusters[0];
    const secondaryCluster = clusters.length > 1 ? clusters[1] : clusters[0];
    const primaryColor = rgbToHexamtu(primaryCluster.averageRgb);
    const secondaryColor = rgbToHexamtu(secondaryCluster.averageRgb);
    const margin = 10;
    const width = imageData.width;
    const height = imageData.height;
    const topClusters = clusterPixelsByConditionamtu(imageData, (_x, y) => y < margin, threshold.top);
    topClusters.sort((a, b) => b.count - a.count);
    const topColor = topClusters.length > 0 ? rgbToHexamtu(topClusters[0].averageRgb) : primaryColor;
    const bottomClusters = clusterPixelsByConditionamtu(imageData, (_x, y) => y >= height - margin, threshold.bottom);
    bottomClusters.sort((a, b) => b.count - a.count);
    const bottomColor = bottomClusters.length > 0 ? rgbToHexamtu(bottomClusters[0].averageRgb) : primaryColor;
    const leftClusters = clusterPixelsByConditionamtu(imageData, (x, _y) => x < margin, threshold.left);
    leftClusters.sort((a, b) => b.count - a.count);
    const leftColor = leftClusters.length > 0 ? rgbToHexamtu(leftClusters[0].averageRgb) : primaryColor;
    const rightClusters = clusterPixelsByConditionamtu(imageData, (x, _y) => x >= width - margin, threshold.right);
    rightClusters.sort((a, b) => b.count - a.count);
    const rightColor = rightClusters.length > 0 ? rgbToHexamtu(rightClusters[0].averageRgb) : primaryColor;
    return {
        primaryColor,
        secondaryColor,
        backgroundColor: {
            top: topColor,
            right: rightColor,
            bottom: bottomColor,
            left: leftColor
        }
    };
}

// 截止至此

function getContrastingTextColorHex(hex, num) {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    if (!result) return '#ffffff';
    const g = parseInt(result[2], 16);
    const b = parseInt(result[3], 16);
    const getLuminance = (r, g, b) => {
        const [rv, gv, bv] = [r, g, b].map(c => {
            const v = c / 255;
            return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
        });
        return 0.2126 * rv + 0.7152 * gv + 0.0722 * bv;
    };

    const bgLum = getLuminance(r, g, b);
    const whiteLum = getLuminance(255, 255, 255);
    const blackLum = getLuminance(0, 0, 0);
    const contrastWhite = (Math.max(bgLum, whiteLum) + 0.05) / (Math.min(bgLum, whiteLum) + 0.05);
    const contrastBlack = (Math.max(bgLum, blackLum) + 0.05) / (Math.min(bgLum, blackLum) + 0.05);

    if (contrastBlack >= contrastWhite-num) {
        return "#000000";
    } else {
        return "#ffffff";
    }
}

// 下面部分的伪莫奈取色来自AI生成
function getMonetColor(hex) {
    const hsv = hexToHsvamtu(hex);
    hsv.s = Math.max(5, hsv.s * 0.45);
    hsv.v = Math.min(92, Math.max(35, hsv.v));
    hsv.h = (hsv.h + 12) % 360;
    return hsvToHexamtu(hsv.h, hsv.s, hsv.v);
}

// module.exports = colorPicker;
// 该脚本内容来自AerMini的GetColor V2 | https://aermini.top/tool/getcolorplus
function hexToHsvamtu(hex) {
    hex = hex.replace('#', '');
    const r = parseInt(hex.substring(0, 2), 16) / 255;
    const g = parseInt(hex.substring(2, 4), 16) / 255;
    const b = parseInt(hex.substring(4, 6), 16) / 255;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    let h, s, v = max;
    const d = max - min;
    s = max === 0 ? 0 : d / max;
    if (max === min) {
        h = 0;
    } else {
        switch (max) {
            case r: h = (g - b) / d + (g < b ? 6 : 0); break;
            case g: h = (b - r) / d + 2; break;
            case b: h = (r - g) / d + 4; break;
        }
        h /= 6;
    }
    return { h: h * 360, s: s * 100, v: v * 100 };
}
function hsvToHexamtu(h, s, v) {
    h /= 360; s /= 100; v /= 100;
    let r, g, b;
    const i = Math.floor(h * 6);
    const f = h * 6 - i;
    const p = v * (1 - s);
    const q = v * (1 - f * s);
    const t = v * (1 - (1 - f) * s);
    switch (i % 6) {
        case 0: r = v, g = t, b = p; break;
        case 1: r = q, g = v, b = p; break;
        case 2: r = p, g = v, b = t; break;
        case 3: r = p, g = q, b = v; break;
        case 4: r = t, g = p, b = v; break;
        case 5: r = v, g = p, b = q; break;
    }
    const toHex = x => Math.round(Math.min(255, Math.max(0, x)) * 255).toString(16).padStart(2, '0');
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}
function isLowSaturationamtu(hex, threshold = 15) { return hexToHsvamtu(hex).s <= threshold; }
function isExtremeLightamtu(hex) { return hexToHsvamtu(hex).v >= 90; }
function isExtremeDarkamtu(hex) { return hexToHsvamtu(hex).v <= 15; }
function generateBackgroundColoramtu(primaryHex, secondaryHex) {
    const p = hexToHsvamtu(primaryHex);
    const s = hexToHsvamtu(secondaryHex);
    const isLowContrast = Math.abs(p.v - s.v) < 30 && p.s < 25 && s.s < 25;
    if (isLowContrast) return '#666699';
    const isCoolPrimary = p.h >= 200 && p.h <= 320;
    const isWarmSecondary = (s.h >= 30 && s.h <= 60) || s.h <= 15;
    if (isCoolPrimary && isWarmSecondary) {
        return hsvToHexamtu(
            s.h < 15 ? 35 : s.h, 
            Math.min(90, s.s + 20), 
            Math.min(80, s.v + 10)  
        );
    }
    const isWarmPrimary = (p.h >= 30 && p.h <= 60) || p.h <= 15;
    const isCoolSecondary = s.h >= 200 && s.h <= 320;
    if (isWarmPrimary && isCoolSecondary) {
        const midHue = ((p.h + s.h) / 2 + 180) % 360; 
        return hsvToHexamtu(
            midHue,
            (p.s + s.s) / 2 * 1.2,
            Math.max(40, (p.v + s.v) / 2)
        );
    }
    const hueDiff = Math.min(Math.abs(p.h - s.h), 360 - Math.abs(p.h - s.h));
    if (hueDiff < 30) {
        return hsvToHexamtu(
            s.h,
            Math.min(80, s.s + 10),  
            p.v > 70 ? Math.max(30, s.v - 20) : Math.min(80, s.v + 20) 
        );
    }
    return hsvToHexamtu(
        (p.h + 30) % 360,  
        Math.min(80, p.s * 0.7),  
        Math.max(30, Math.min(80, p.v * 1.2)) 
    );
}

async function extractColor(url) {
    const helperScript = `
        ${rgbToLabamtu.toString()}
        ${labDistanceamtu.toString()}
        ${rgbToHexamtu.toString()}
        ${loadImageamtu.toString()}
        ${getImageDataFromImageamtu.toString()}
        ${clusterPixelsByConditionamtu.toString()}
        ${__handleAutoHueOptionsamtu.toString()}
        ${hexToHsvamtu.toString()}
        ${hsvToHexamtu.toString()}
        ${generateBackgroundColoramtu.toString()}
        ${getContrastingTextColorHex.toString()}
        ${getMonetColor.toString()}
        ${colorPickeramtu.toString()}
    `;
    return new Promise((resolve) => {
        let settled = false;
        const finish = (val) => { if (!settled) { settled = true; cleanUp(); resolve(val); } };
        const iframe = document.createElement('iframe');
        iframe.style.display = 'none';
        const safeUrl = JSON.stringify(String(url || ''));
        iframe.srcdoc = `
            <!DOCTYPE html><html><head><script>
            ${helperScript}
            window.onload = function() {
                colorPickeramtu(${safeUrl}, { maxSize: 200 }).then(result => {
                        const textColor = getContrastingTextColorHex(result.primaryColor, -8);
                    window.parent.postMessage({
                        type: 'ColorResult',
                        data: { main: result.primaryColor, text: textColor }
                    }, '*');
                }).catch(e => window.parent.postMessage({type:'ColorError'}, '*'));
            };
            <\/script></head></html>
        `;
        const cleanUp = () => {
            clearTimeout(timer);
            window.removeEventListener('message', handler);
            if (iframe && iframe.parentNode) {
                document.body.removeChild(iframe);
            }
        };
        const handler = (event) => {
            if (event.source !== iframe.contentWindow) return;
            if (!event.data || typeof event.data !== 'object') return;
            if (event.data.type === 'ColorResult') {
                finish(JSON.stringify(event.data.data));
            } else if (event.data.type === 'ColorError') {
                finish("{}");
            }
        };
        const timer = setTimeout(() => { finish("{}"); }, 5000);
        window.addEventListener('message', handler);
        document.body.appendChild(iframe);
    });
}